  ('"You can sit ___ you like." Herhangi bir yere oturabileceğini anlatmak için hangisi uygundur?', 'anywhere', ['nowhere', 'somewhere', 'everywhere'], 'Olumlu cümlede "anywhere" "nereye istersen, herhangi bir yere" anlamında kullanılır.'),
  ('"A: Which colour do you prefer, red or blue? B: I don\'t like ___ of them." boşluğa hangisi gelmelidir?', 'either', ['neither', 'both', 'none'], 'İki seçenekten hiçbirinin sevilmediği olumsuz fiille (don\'t like) "either" kullanılarak anlatılır.'),
  ('"Each of the students ___ a different project." boşluğa hangisi gelmelidir?', 'has', ['have', 'are having', 'having'], '"Each of + çoğul isim" yapısında fiil tekil olur.'),
  ('"I live ___ 25 Atatürk Street." boşluğa hangisi gelmelidir?', 'at', ['in', 'on', 'to'], 'Kapı numarası içeren tam adreslerden önce "at" kullanılır.'),
  ('"See you ___ the weekend!" İngiliz İngilizcesinde boşluğa hangisi gelmelidir?', 'at', ['in', 'to', 'since'], 'İngiliz İngilizcesinde "at the weekend" kullanılır; Amerikan İngilizcesinde "on the weekend" yaygındır.'),
  ('"Nobody called me while I was out, ___?" boşluğa hangisi gelmelidir?', 'did they', ['didn\'t they', 'did he', 'was it'], '"Nobody" olumsuz anlamlıdır, bu yüzden tag olumlu olur; "nobody/somebody" için tag\'de "they" kullanılır.'),
  ('"Open the window, ___?" Kibar bir rica bildiren question tag hangisidir?', 'will you', ['do you', 'shall we', 'are you'], 'Emir cümlelerinde kibarlık için "will you?" ya da "would you?" tag\'i kullanılır.'),
  ('"He was ill. He went to work." İki cümleyi "despite" kullanarak doğru biçimde birleştiren seçenek hangisidir?', 'Despite being ill, he went to work.', ['Despite he was ill, he went to work.', 'Despite of being ill, he went to work.', 'Despite ill, he went to work being.'], '"Despite" ardından V-ing ya da isim alır; "despite of" ve "despite + cümle" yanlıştır.'),
  ('"What happened at the meeting?" sorusunda "what" cümlenin hangi öğesidir?', 'Öznedir', ['Nesnedir', 'Zarf tümlecidir', 'Yüklemdir'], '"What" öznedir; bu nedenle yardımcı fiil "did" kullanılmaz ve fiil doğrudan geçmiş biçimde gelir.'),
  ('"The police ___ looking for the missing child." boşluğa hangisi gelmelidir?', 'are', ['is', 'was', 'has'], '"Police" her zaman çoğul fiil alan bir topluluk ismidir.'),
  ('"I was tired. ___, I continued working until midnight." boşluğa hangisi gelmelidir?', 'Nevertheless', ['Because', 'Although', 'In case'], '"Nevertheless" (yine de) cümle başında zıtlık bildirir; "although" ise iki cümleyi tek cümlede bağlar.'),
  ('"How many cups of coffee ___ today?" Günün henüz bitmediği düşünüldüğünde boşluğa en uygun seçenek hangisidir?', 'have you drunk', ['did you drink yesterday', 'do you drunk', 'are you drunk'], '"Today" henüz bitmemiş bir zaman dilimidir; bu dilim içinde tamamlanan eylemler present perfect ile sorulur.'),
  ('"My parents ___ married for ten years when I was born." boşluğa hangisi gelmelidir?', 'had been', ['have been', 'are', 'will be'], 'Geçmişteki bir ana (doğum) kadar süren durum past perfect ile anlatılır.'),
  ('"___ rich should help ___ poor." boşluklara sırasıyla hangisi gelmelidir?', 'The / the', ['A / a', 'An / the', 'Some / a'], '"The + sıfat" yapısı bir insan grubunu (zenginler, yoksullar) anlatır.'),
  ('"The meeting is ___ Wednesday afternoon." boşluğa hangisi gelmelidir?', 'on', ['in', 'at', 'during the'], 'Belirli bir günün bölümü (Wednesday afternoon) "on" ile kullanılır.'),
  ('"The more you read, ___ your vocabulary becomes." boşluğa hangisi gelmelidir?', 'the richer', ['richer', 'the richest', 'more rich'], '"The + karşılaştırma ..., the + karşılaştırma ..." yapısında iki bölümde de "the" kullanılır.'),
  ('"It was such ___ that we couldn\'t go out." boşluğa hangisi gelmelidir?', 'a cold day', ['cold day', 'so cold', 'a day cold'], '"Such + a + sıfat + tekil isim + that" kalıbı kullanılır.'),
  ('"She was the first woman ___ win the prize." boşluğa hangisi gelmelidir?', 'to', ['who she', 'that she', 'for'], '"The first/the last + isim" ardından genellikle "to + yalın fiil" gelir.'),
  ('"The novel ___ into more than forty languages so far." boşluğa hangisi gelmelidir?', 'has been translated', ['was translating', 'has translated', 'translates'], '"So far" present perfect gerektirir; romanın kendisi çeviren değil çevrilen olduğundan edilgen yapı kullanılır.'),
  ('"Who wrote this poem?" sorusu ile "Who did you write this poem for?" sorusu arasındaki fark nedir?', 'İlki şiiri yazanı, ikincisi şiirin kime yazıldığını sorar.', ['İkisi de şiiri yazan kişiyi sorar.', 'İlki şiirin kime yazıldığını, ikincisi yazanı sorar.', 'İlki geçmişte, ikincisi gelecekte yazılacak şiiri sorar.'], 'İlk soruda "who" öznedir ve "did" kullanılmaz; ikincide "you" öznedir, "who" edatın nesnesidir.'),
  ('"He\'s got two sisters, ___?" boşluğa hangisi gelmelidir?', 'hasn\'t he', ['isn\'t he', 'doesn\'t he', 'hasn\'t got he'], '"He\'s got" = "He has got"; question tag\'de "has" yardımcı fiili kullanılır: hasn\'t he?'),
];
